cd /tmp && cat > gen.mjs <<'EOF'
// Find all runs of \p{Nd} and split into aligned decades.
const re = /\p{Nd}/u;
const starts = [];
let runStart = -1, prev = -1;
for (let cp = 0; cp <= 0x10FFFF; cp++) {
  if (cp >= 0xD800 && cp <= 0xDFFF) continue;
  const isNd = re.test(String.fromCodePoint(cp));
  if (isNd) { if (runStart < 0) runStart = cp; prev = cp; }
  else if (runStart >= 0) { const len = prev - runStart + 1;
    if (len % 10 !== 0) console.error("BAD RUN", runStart.toString(16), len);
    for (let s = runStart; s <= prev; s += 10) starts.push(s);
    runStart = -1; }
}
console.log("decades:", starts.length);
console.log(JSON.stringify(starts));
EOF
node gen.mjs > /tmp/nd.txt 2>/tmp/nd.err; head -c 400 /tmp/nd.txt; echo; echo "[err]"; cat /tmp/nd.err
echo "=== astral digit test on binary ==="
./test20_executable --a '𝟕' --b 1 --c 3 --d 4 --e 5 --f 6 2>&1 | head -2

