/**
 * Python-style exception objects.
 *
 * The original program lets exceptions escape to the top level, so the runtime
 * needs to know an exception's Python type name and message in order to render
 * a faithful traceback.  Plain JS `Error` carries neither in a stable way, so
 * every raised condition is modelled explicitly here.
 */

/** Base class for every emulated Python exception. */
export class PyException extends Error {
  /**
   * @param {string} pyType   Python class name, e.g. 'ZeroDivisionError'.
   * @param {string} pyMessage  The `str(exc)` payload.
   */
  constructor(pyType, pyMessage) {
    super(`${pyType}: ${pyMessage}`);
    this.name = pyType;
    this.pyType = pyType;
    this.pyMessage = pyMessage;
    /**
     * Frames appended below the `<module>` frame when the traceback is
     * rendered.  Each entry is `{ file, line, name }`; the frozen interpreter
     * prints library frames without their source text, matching this shape.
     */
    this.pyFrames = [];
  }

  /** The final `Type: message` line of a traceback. */
  formatExceptionLine() {
    return this.pyMessage === '' ? this.pyType : `${this.pyType}: ${this.pyMessage}`;
  }
}

export class PyZeroDivisionError extends PyException {
  constructor(pyMessage) {
    super('ZeroDivisionError', pyMessage);
  }
}

export class PyValueError extends PyException {
  constructor(pyMessage) {
    super('ValueError', pyMessage);
  }
}

export class PyTypeError extends PyException {
  constructor(pyMessage) {
    super('TypeError', pyMessage);
  }
}

/** True when `err` is one of the emulated Python exceptions. */
export function isPyException(err) {
  return err instanceof PyException;
}

/**
 * Attach the library frames that CPython would have pushed before raising.
 * Returns the same exception so it can be thrown inline.
 */
export function withFrames(err, frames) {
  err.pyFrames = frames;
  return err;
}

