/**
 * `repr()` for strings, matching CPython closely enough for CLI diagnostics.
 *
 * argparse embeds the offending value with `%r`, so the quoting and escaping
 * rules are observable in the program's stderr.
 */

import { isPyPrintable } from './unicode-data.mjs';

function escapeCodePoint(ch) {
  const cp = ch.codePointAt(0);
  if (cp < 0x100) return `\\x${cp.toString(16).padStart(2, '0')}`;
  if (cp < 0x10000) return `\\u${cp.toString(16).padStart(4, '0')}`;
  return `\\U${cp.toString(16).padStart(8, '0')}`;
}

/**
 * Render `value` the way `repr()` would: single quotes by default, double
 * quotes when the text contains a single quote but no double quote.
 */
export function pyRepr(value) {
  const quote = value.includes("'") && !value.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of value) {
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += `\\${ch}`;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (isPyPrintable(ch)) {
      out += ch;
    } else {
      out += escapeCodePoint(ch);
    }
  }
  return out + quote;
}

