/**
 * Standard-stream plumbing.
 *
 * CPython buffers stdout the same way C does -- line buffered on a terminal,
 * block buffered otherwise, flushed once at interpreter shutdown -- while
 * stderr is written through immediately.  That difference is observable
 * whenever the program dies mid-run with output already produced: the
 * traceback appears *before* the pending stdout lines in a merged stream.
 * Reproducing the buffering keeps that ordering intact.
 */

import { writeSync } from 'node:fs';

const STDOUT_FD = 1;
const STDERR_FD = 2;
const BLOCK_SIZE = 8192;

const lineBuffered = process.stdout.isTTY === true;

/** @type {string[]} */
let pending = [];
let pendingBytes = 0;

/** Write raw bytes, tolerating the transient EAGAIN a busy pipe can produce. */
function writeAll(fd, text) {
  const data = Buffer.from(text, 'utf8');
  let offset = 0;
  while (offset < data.length) {
    try {
      offset += writeSync(fd, data, offset, data.length - offset);
    } catch (err) {
      if (err.code === 'EAGAIN') continue;
      if (err.code === 'EPIPE') return;
      throw err;
    }
  }
}

/** Push everything buffered for stdout to the file descriptor. */
export function flushStdout() {
  if (pending.length === 0) return;
  const text = pending.join('');
  pending = [];
  pendingBytes = 0;
  writeAll(STDOUT_FD, text);
}

/** Buffered stdout write, honouring the active buffering mode. */
export function writeStdout(text) {
  if (text === '') return;
  pending.push(text);
  pendingBytes += Buffer.byteLength(text, 'utf8');
  if (lineBuffered ? text.includes('\n') : pendingBytes >= BLOCK_SIZE) {
    flushStdout();
  }
}

/** Unbuffered stderr write. */
export function writeStderr(text) {
  if (text === '') return;
  writeAll(STDERR_FD, text);
}

/** `print(value)` for an already-stringified value. */
export function pyPrint(text) {
  writeStdout(`${text}\n`);
}

/** Flush pending output and terminate with `code`, as interpreter shutdown does. */
export function exitWith(code) {
  flushStdout();
  process.exit(code);
}

