/**
 * Traceback rendering for exceptions that reach the top level.
 *
 * The interpreter prints the offending source line together with the
 * fine-grained anchors introduced in 3.11 (`^` under the failing operation,
 * `~` under the rest of the expression), then one bare frame per library call
 * that was on the stack, then the exception line itself.
 */

import { writeStderr } from './stdio.mjs';

const SOURCE_INDENT = '    ';

/**
 * Build the anchor line that sits under a source line.
 *
 * @param {[number, number]} span  Half-open column range of the expression.
 * @param {[number, number]|null} operator  Column range of the operator token
 *   for a binary operation; `null` marks the whole span with carets.
 */
export function anchorLine(span, operator) {
  const [start, end] = span;
  let marks = '';
  if (operator === null) {
    marks = '^'.repeat(end - start);
  } else {
    const [opStart, opEnd] = operator;
    marks =
      '~'.repeat(opStart - start) +
      '^'.repeat(opEnd - opStart) +
      '~'.repeat(end - opEnd);
  }
  return ' '.repeat(SOURCE_INDENT.length + start) + marks;
}

/**
 * Render and emit a traceback.
 *
 * @param {{file: string, line: number, source: string, anchors: string|null}} origin
 *   The `<module>` frame: where the statement lives and how it is annotated.
 * @param {{file: string, line: number, name: string}[]} frames
 *   Library frames below it, outermost first.  The frozen interpreter has no
 *   source for these, so only their headers are printed.
 * @param {string} exceptionLine  The trailing `Type: message` line.
 */
export function printTraceback(origin, frames, exceptionLine) {
  let out = 'Traceback (most recent call last):\n';
  out += `  File "${origin.file}", line ${origin.line}, in <module>\n`;
  out += `${SOURCE_INDENT}${origin.source}\n`;
  if (origin.anchors !== null) out += `${origin.anchors}\n`;
  for (const frame of frames) {
    out += `  File "${frame.file}", line ${frame.line}, in ${frame.name}\n`;
  }
  out += `${exceptionLine}\n`;
  writeStderr(out);
}

