/**
 * Help and usage rendering, mirroring `argparse.HelpFormatter`.
 *
 * The layout depends on the terminal width, which the interpreter reads from
 * `COLUMNS` and falls back to 80 for, so the same lookup happens here.
 */

const INDENT_INCREMENT = 2;
const MAX_HELP_POSITION = 24;
const USAGE_PREFIX = 'usage: ';

/** Terminal width argparse formats against: `shutil.get_terminal_size().columns - 2`. */
export function terminalWidth() {
  const declared = process.env.COLUMNS;
  if (declared !== undefined) {
    // Python accepts any integer literal here and ignores non-positive values.
    if (/^[+-]?\d+$/.test(declared.trim())) {
      let columns = 0;
      const body = declared.trim().replace(/^\+/, '');
      const negative = body.startsWith('-');
      for (const ch of negative ? body.slice(1) : body) {
        columns = columns * 10 + (ch.charCodeAt(0) - 48);
      }
      if (negative) columns = -columns;
      if (columns > 0) return columns - 2;
    }
  }
  if (process.stdout.isTTY && process.stdout.columns > 0) {
    return process.stdout.columns - 2;
  }
  return 78;
}

/** Greedy wrap, equivalent to `textwrap.wrap` for the short help strings used here. */
function wrapText(text, width) {
  const words = text.split(/\s+/).filter((word) => word !== '');
  const lines = [];
  let current = '';
  for (const word of words) {
    if (current === '') {
      current = word;
    } else if (current.length + 1 + word.length <= width) {
      current += ` ${word}`;
    } else {
      lines.push(current);
      current = word;
    }
  }
  if (current !== '') lines.push(current);
  return lines.length === 0 ? [''] : lines;
}

/** `--a A` / `-h, --help` -- how an action is spelled in the options list. */
export function formatInvocation(action) {
  if (action.nargs === 0) return action.optionStrings.join(', ');
  return action.optionStrings.map((opt) => `${opt} ${action.metavar}`).join(', ');
}

/** The bracketed form used inside the usage line. */
function formatUsagePart(action) {
  const invocation =
    action.nargs === 0
      ? action.optionStrings[0]
      : `${action.optionStrings[0]} ${action.metavar}`;
  return action.required ? invocation : `[${invocation}]`;
}

/**
 * Wrap a list of usage parts, reproducing argparse's `get_lines` helper.
 * `prefix` is only passed for the first block, whose first line is unindented.
 */
function getLines(parts, indent, textWidth, prefix) {
  const lines = [];
  let line = [];
  let lineLength = prefix === null ? indent.length - 1 : prefix.length - 1;
  for (const part of parts) {
    if (lineLength + 1 + part.length > textWidth && line.length > 0) {
      lines.push(indent + line.join(' '));
      line = [];
      lineLength = indent.length - 1;
    }
    line.push(part);
    lineLength += 1 + part.length;
  }
  if (line.length > 0) lines.push(indent + line.join(' '));
  if (prefix !== null && lines.length > 0) lines[0] = lines[0].slice(indent.length);
  return lines;
}

