export function formatUsage(prog, actions, width) {
  const parts = actions.map(formatUsagePart);
  let usage = [prog, ...parts].join(' ');
  const textWidth = width;

  if (USAGE_PREFIX.length + usage.length > textWidth) {
    if (USAGE_PREFIX.length + prog.length <= 0.75 * textWidth) {
      const indent = ' '.repeat(USAGE_PREFIX.length + prog.length + 1);
      usage = getLines([prog, ...parts], indent, textWidth, USAGE_PREFIX).join('\n');
    } else {
      const indent = ' '.repeat(USAGE_PREFIX.length);
      let lines = getLines(parts, indent, textWidth, null);
      if (lines.length > 1) {
        lines = getLines(parts, indent, textWidth, null);
      }
      usage = [prog, ...lines].join('\n');
    }
  }
  return `${USAGE_PREFIX}${usage}\n`;
}

/** The complete `--help` text, terminated by exactly one newline. */
export function formatHelp(prog, actions, width) {
  const invocations = actions.map(formatInvocation);
  const actionMaxLength = Math.max(
    ...invocations.map((text) => text.length + INDENT_INCREMENT),
  );
  const maxHelpPosition = Math.min(
    MAX_HELP_POSITION,
    Math.max(width - 20, INDENT_INCREMENT * 2),
  );
  const helpPosition = Math.min(actionMaxLength + 2, maxHelpPosition);
  const actionWidth = helpPosition - INDENT_INCREMENT - 2;
  const helpWidth = Math.max(width - helpPosition, 11);

  let out = formatUsage(prog, actions, width);
  out += '\noptions:\n';

  actions.forEach((action, index) => {
    const invocation = invocations[index];
    if (!action.help) {
      out += `${' '.repeat(INDENT_INCREMENT)}${invocation}\n`;
      return;
    }
    const helpLines = wrapText(action.help, helpWidth);
    if (invocation.length <= actionWidth) {
      out += `${' '.repeat(INDENT_INCREMENT)}${invocation.padEnd(actionWidth)}  ${helpLines[0]}\n`;
    } else {
      out += `${' '.repeat(INDENT_INCREMENT)}${invocation}\n`;
      out += `${' '.repeat(helpPosition)}${helpLines[0]}\n`;
    }
    for (const extra of helpLines.slice(1)) {
      out += `${' '.repeat(helpPosition)}${extra}\n`;
    }
  });

  return out;
}

