/**
 * A faithful re-implementation of the `argparse` behaviour this program
 * depends on: six required long options taking an `int`, plus the implicit
 * `-h/--help`.
 *
 * The interesting part is not the happy path but the classification rules --
 * which tokens count as options, how `--`, `=` and concatenated short options
 * are treated, and the order in which the possible errors are reported.  All
 * of it is observable through stderr and the exit status.
 */

import { pyRepr } from '../core/repr.mjs';
import { pyIntFromString } from '../core/int-parse.mjs';
import { PyException } from '../core/errors.mjs';
import { writeStdout, writeStderr, exitWith } from '../runtime/stdio.mjs';
import { formatHelp, formatUsage, terminalWidth } from './help-format.mjs';

/** Raised for a problem attributable to one specific option. */
class ArgumentError extends Error {
  constructor(action, message) {
    const name = action === null ? null : action.optionStrings.join('/');
    super(name === null ? message : `argument ${name}: ${message}`);
    this.formatted = name === null ? message : `argument ${name}: ${message}`;
  }
}

/** Raised to unwind to `parseArgs`, which turns it into usage + exit 2. */
class ParserExit extends Error {
  constructor(message) {
    super(message);
    this.parserMessage = message;
  }
}

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

export class ArgumentParser {
  /** @param {string} prog  Program name used in usage and error lines. */
  constructor(prog) {
    this.prog = prog;
    this.actions = [];
    this.optionStringActions = new Map();

    this.addArgument(['-h', '--help'], {
      dest: 'help',
      nargs: 0,
      required: false,
      help: 'show this help message and exit',
    });
  }

  addArgument(optionStrings, options) {
    const action = {
      optionStrings,
      dest: options.dest,
      nargs: options.nargs === undefined ? null : options.nargs,
      required: options.required === true,
      help: options.help === undefined ? null : options.help,
      metavar: options.dest.toUpperCase(),
      type: options.type === undefined ? null : options.type,
    };
    this.actions.push(action);
    for (const optionString of optionStrings) {
      this.optionStringActions.set(optionString, action);
    }
    return action;
  }

  formatUsage() {
    return formatUsage(this.prog, this.actions, terminalWidth());
  }

  formatHelp() {
    return formatHelp(this.prog, this.actions, terminalWidth());
  }

  /** Print usage plus one error line to stderr and exit with status 2. */
  error(message) {
    writeStderr(this.formatUsage());
    writeStderr(`${this.prog}: error: ${message}\n`);
    exitWith(2);
  }

  /**
   * Classify a single token.
   *
   * @returns {null | {action, optionString, sep, explicitArg}}
   *   `null` means "this is a value, not an option".  A returned tuple with a
   *   null `action` means "looks like an option, but no such option exists".
   */
  parseOptional(argString) {
    if (argString === '') return null;
    if (argString[0] !== '-') return null;

    const exact = this.optionStringActions.get(argString);
    if (exact !== undefined) {
      return { action: exact, optionString: argString, sep: null, explicitArg: null };
    }
    if (argString.length === 1) return null;

    const equals = argString.indexOf('=');
    if (equals >= 0) {
      const head = argString.slice(0, equals);
      const action = this.optionStringActions.get(head);
      if (action !== undefined) {
        return {
          action,
          optionString: head,
          sep: '=',
          explicitArg: argString.slice(equals + 1),
        };
      }
    }

    const candidates = this.getOptionTuples(argString);
    if (candidates.length > 1) {
      const matches = candidates.map((tuple) => tuple.optionString).join(', ');
      throw new ParserExit(
        `ambiguous option: ${argString} could match ${matches}`,
      );
    }
    if (candidates.length === 1) return candidates[0];

    // A lone negative number is a value, since no option looks like one.
    if (NEGATIVE_NUMBER.test(argString)) return null;
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, sep: null, explicitArg: null };
  }

  /** Prefix matches for an unrecognised option-looking token. */
  getOptionTuples(argString) {
    const result = [];
    if (argString[1] === '-') {
      const equals = argString.indexOf('=');
      const prefix = equals >= 0 ? argString.slice(0, equals) : argString;
      const sep = equals >= 0 ? '=' : null;
      const explicitArg = equals >= 0 ? argString.slice(equals + 1) : null;
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(prefix)) {
          result.push({ action, optionString, sep, explicitArg });
        }
      }
    } else {
      // Single dash: the tail may be a concatenated argument.
      const shortPrefix = argString.slice(0, 2);
      const shortExplicitArg = argString.slice(2);
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString === shortPrefix) {
          result.push({ action, optionString, sep: '', explicitArg: shortExplicitArg });
        } else if (optionString.startsWith(argString)) {
          result.push({ action, optionString, sep: null, explicitArg: null });
        }
      }
    }
    return result;
  }

  /** Convert one raw value through the action's `type`, argparse-style. */
  convert(action, text) {
    try {
      return action.type(text);
    } catch (err) {
      if (err instanceof PyException) {
        throw new ArgumentError(action, `invalid int value: ${pyRepr(text)}`);
      }
      throw err;
    }
  }

  /**
   * Parse `argv`, returning the namespace of converted values.  Exits the
   * process directly for `--help` and for every user error.
   */
  parseArgs(argv) {
    try {
      return this.parseKnownArgs(argv);
    } catch (err) {
      if (err instanceof ArgumentError) this.error(err.formatted);
      if (err instanceof ParserExit) this.error(err.parserMessage);
      throw err;
    }
  }

  parseKnownArgs(argv) {
    // Phase one: label every token. Everything following a bare `--` is a
    // value, and the `--` itself belongs to neither class.
    const pattern = [];
    const tuples = new Map();
    let afterSeparator = false;
    for (let i = 0; i < argv.length; i++) {
      if (afterSeparator) {
        pattern.push('A');
        continue;
      }
      if (argv[i] === '--') {
        pattern.push('-');
        afterSeparator = true;
        continue;
      }
      const tuple = this.parseOptional(argv[i]);
      if (tuple === null) {
        pattern.push('A');
      } else {
        tuples.set(i, tuple);
        pattern.push('O');
      }
    }

    const namespace = Object.create(null);
    const seen = new Set();
    const extras = [];

    // Phase two: walk left to right, consuming options and their values.
    let index = 0;
    while (index < argv.length) {
      if (!tuples.has(index)) {
        extras.push(argv[index]);
        index += 1;
        continue;
      }
      index = this.consumeOptional(argv, pattern, tuples.get(index), index, {
        namespace,
        seen,
        extras,
      });
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.optionStrings.join('/'));
    if (missing.length > 0) {
      throw new ParserExit(
        `the following arguments are required: ${missing.join(', ')}`,
      );
    }
    if (extras.length > 0) {
      throw new ParserExit(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  /** Consume the option at `startIndex`; returns the next index to look at. */
  consumeOptional(argv, pattern, tuple, startIndex, state) {
    let { action, optionString, sep, explicitArg } = tuple;
    const queued = [];
    let stop = startIndex;

    for (;;) {
      if (action === null) {
        // An option-looking token nobody claims: report it as a leftover.
        state.extras.push(argv[startIndex]);
        return startIndex + 1;
      }

      if (explicitArg !== null) {
        const argCount = action.nargs === 0 ? 0 : 1;

        if (argCount === 0 && optionString[1] !== '-' && explicitArg !== '') {
          // `-xyz` may be a run of concatenated single-character options, but
          // only when the tail was not introduced by `=` or another dash.
          if (sep === '=' || explicitArg[0] === '-') {
            throw new ArgumentError(
              action,
              `ignored explicit argument ${pyRepr(explicitArg)}`,
            );
          }
          queued.push({ action, args: [], optionString });
          const nextOptionString = `${optionString[0]}${explicitArg[0]}`;
          const rest = explicitArg.slice(1);
          const nextAction = this.optionStringActions.get(nextOptionString);
          if (nextAction !== undefined) {
            action = nextAction;
            optionString = nextOptionString;
            sep = '';
            explicitArg = rest === '' ? null : rest;
            continue;
          }
          state.extras.push(`${optionString[0]}${explicitArg}`);
          stop = startIndex + 1;
          break;
        }

        if (argCount === 1) {
          queued.push({ action, args: [explicitArg], optionString });
          stop = startIndex + 1;
          break;
        }

        throw new ArgumentError(
          action,
          `ignored explicit argument ${pyRepr(explicitArg)}`,
        );
      }

      // No attached value: take the following token, but only if it is one.
      if (action.nargs === 0) {
        queued.push({ action, args: [], optionString });
        stop = startIndex + 1;
        break;
      }
      if (pattern[startIndex + 1] !== 'A') {
        throw new ArgumentError(action, 'expected one argument');
      }
      queued.push({ action, args: [argv[startIndex + 1]], optionString });
      stop = startIndex + 2;
      break;
    }

    for (const item of queued) this.takeAction(item, state);
    return stop;
  }

  takeAction({ action, args }, state) {
    state.seen.add(action);
    if (action.dest === 'help') {
      writeStdout(this.formatHelp());
      exitWith(0);
    }
    state.namespace[action.dest] = this.convert(action, args[0]);
  }
}

