/**
 * Command-line recovery.
 *
 * Python decodes `argv` with the filesystem encoding and the `surrogateescape`
 * error handler, so a byte that is not valid UTF-8 survives as U+DCxx rather
 * than being folded into a replacement character.  That difference is visible
 * whenever an argument is echoed back through `repr()` in an error message, so
 * the original bytes are recovered from the kernel when possible.
 */

import { readFileSync } from 'node:fs';

/** Decode UTF-8, mapping every undecodable byte to its lone surrogate. */
export function decodeSurrogateEscape(bytes) {
  let out = '';
  let i = 0;
  while (i < bytes.length) {
    const lead = bytes[i];
    if (lead < 0x80) {
      out += String.fromCharCode(lead);
      i += 1;
      continue;
    }

    let continuationCount = 0;
    let value = 0;
    let lowerBound = 0;
    if (lead >= 0xc2 && lead <= 0xdf) {
      continuationCount = 1;
      value = lead & 0x1f;
      lowerBound = 0x80;
    } else if (lead >= 0xe0 && lead <= 0xef) {
      continuationCount = 2;
      value = lead & 0x0f;
      lowerBound = 0x800;
    } else if (lead >= 0xf0 && lead <= 0xf4) {
      continuationCount = 3;
      value = lead & 0x07;
      lowerBound = 0x10000;
    } else {
      out += String.fromCharCode(0xdc00 + lead);
      i += 1;
      continue;
    }

    let valid = true;
    for (let k = 1; k <= continuationCount; k++) {
      const byte = bytes[i + k];
      if (byte === undefined || (byte & 0xc0) !== 0x80) {
        valid = false;
        break;
      }
      value = value * 64 + (byte & 0x3f);
    }
    if (
      !valid ||
      value < lowerBound ||
      value > 0x10ffff ||
      (value >= 0xd800 && value <= 0xdfff)
    ) {
      out += String.fromCharCode(0xdc00 + lead);
      i += 1;
      continue;
    }

    out += String.fromCodePoint(value);
    i += continuationCount + 1;
  }
  return out;
}

/**
 * The user-supplied arguments, byte-exact where the platform allows it.
 * Falls back to the runtime's own (lossy) decoding when the raw command line
 * cannot be read or does not line up with it.
 */
export function readArgv() {
  const decoded = process.argv.slice(2);
  try {
    const raw = readFileSync('/proc/self/cmdline');
    const parts = [];
    let start = 0;
    for (let i = 0; i < raw.length; i++) {
      if (raw[i] === 0) {
        parts.push(raw.subarray(start, i));
        start = i + 1;
      }
    }
    if (start < raw.length) parts.push(raw.subarray(start));
    if (parts.length < decoded.length) return decoded;

    // The user's arguments are always the trailing entries of the real argv.
    const tail = parts.slice(parts.length - decoded.length);
    for (let i = 0; i < decoded.length; i++) {
      if (tail[i].toString('utf8') !== decoded[i]) return decoded;
    }
    return tail.map(decodeSurrogateEscape);
  } catch {
    return decoded;
  }
}

