const LINE_15 = 'f2 = Fraction(args.c, args.d)  # API调用2: 创建分数';
const LINE_17 = 'f3 = Fraction(args.e, args.f)  # API调用3: 创建分数';
const LINE_27 = 'harmonic_mean = 3 / (1/f1 + 1/f2 + 1/f3)  # API调用8: 分数运算';

/**
 * Describe one failure site.
 *
 * @param {number} line     1-based line number in the original file.
 * @param {string} source   The full source line.
 * @param {string} expr     The sub-expression the anchors cover.
 * @param {string|null} operator  Operator token inside `expr` for a binary
 *   operation; `null` marks the whole sub-expression with carets.
