/**
 * Node port of `test20.py`.
 *
 * The original builds three fractions from six required integer options and
 * prints eleven derived values.  This file mirrors that statement by
 * statement; everything it leans on -- unbounded integers, `Fraction`
 * semantics, `argparse`, Python's stream buffering and traceback format --
 * lives in ./lib.
 *
 * Usage: node test20.mjs --a A --b B --c C --d D --e E --f F
 */

import { ArgumentParser } from './lib/cli/argument-parser.mjs';
import { isPyException } from './lib/core/errors.mjs';
import { pyIntFromString } from './lib/core/int-parse.mjs';
import { PyInt } from './lib/core/integer.mjs';
import {
  Fraction,
  trueDivideForward,
  trueDivideReverse,
} from './lib/fractions/fraction.mjs';
import { SITES } from './lib/program/source-map.mjs';
import { readArgv } from './lib/runtime/argv.mjs';
import { exitWith, pyPrint } from './lib/runtime/stdio.mjs';
import { printTraceback } from './lib/runtime/traceback.mjs';

/**
 * Program name used in usage and error lines.  Python derives it from
 * `argv[0]`; the reference build is invoked as `test20_executable`, so its
 * diagnostics are reproduced verbatim.
 */
const PROG = 'test20_executable';

/** Evaluate one statement, reporting an escaping exception the way Python does. */
function step(siteName, thunk) {
  try {
    return thunk();
  } catch (err) {
    if (!isPyException(err)) throw err;
    printTraceback(SITES[siteName], err.pyFrames, err.formatExceptionLine());
    exitWith(1);
    return undefined;
  }
}

/** `print(fraction)` -- rendering can fail, so it is a statement of its own. */
function printFraction(siteName, fraction) {
  pyPrint(step(siteName, () => fraction.toDisplayString()));
}

const parser = new ArgumentParser(PROG);
for (const name of ['a', 'b', 'c', 'd', 'e', 'f']) {
  parser.addArgument([`--${name}`], {
    dest: name,
    type: pyIntFromString,
    required: true,
  });
}
const args = parser.parseArgs(readArgv());

const ONE = Fraction.fromInt(PyInt.fromSmall(1));
const THREE = Fraction.fromInt(PyInt.fromSmall(3));

const f1 = step('makeF1', () => new Fraction(args.a, args.b));
printFraction('printF1', f1);
const f2 = step('makeF2', () => new Fraction(args.c, args.d));
printFraction('printF2', f2);
const f3 = step('makeF3', () => new Fraction(args.e, args.f));
printFraction('printF3', f3);

const sum1 = f1.plus(f2);
printFraction('printSum1', sum1);
const sum2 = sum1.plus(f3);
printFraction('printSum2', sum2);

const product1 = f1.times(f2);
printFraction('printProduct1', product1);
const product2 = product1.times(f3);
printFraction('printProduct2', product2);

const reciprocal1 = step('reciprocal1', () => trueDivideReverse(ONE, f1));
const reciprocal2 = step('reciprocal2', () => trueDivideReverse(ONE, f2));
const reciprocalSum = reciprocal1.plus(reciprocal2);
const reciprocal3 = step('reciprocal3', () => trueDivideReverse(ONE, f3));
const harmonicMean = step('harmonicMean', () =>
  trueDivideReverse(THREE, reciprocalSum.plus(reciprocal3)),
);
printFraction('printHarmonicMean', harmonicMean);

const arithmeticMean = trueDivideForward(f1.plus(f2).plus(f3), THREE);
printFraction('printArithmeticMean', arithmeticMean);

const comparison1 = f1.greaterThan(f2);
pyPrint(comparison1 ? 'True' : 'False');
const comparison2 = f2.greaterThan(f3);
pyPrint(comparison2 ? 'True' : 'False');

exitWith(0);

