const reciprocal2 = step('reciprocal2', () => trueDivideReverse(ONE, f2));
const reciprocalSum = reciprocal1.plus(reciprocal2);
const reciprocal3 = step('reciprocal3', () => trueDivideReverse(ONE, f3));
