/**
 * Traceback rendering for exceptions that reach the top level.
 *
 * Two details matter for fidelity:
 *
 *  - The source line is looked up through the equivalent of `linecache`, i.e.
 *    the recorded file name resolved against the working directory.  The
 *    reference build ships no sources, so the line appears only when a
 *    `test20.py` happens to sit next to the caller -- and then it is that
 *    file's text that gets echoed.
 *  - When the line is available it is followed by the fine-grained anchors
 *    added in 3.11: `^` under the failing operator, `~` under the rest of the
 *    expression, with columns taken relative to the stripped line.
 */

import { readFileSync } from 'node:fs';

import { writeStderr } from './stdio.mjs';

const SOURCE_INDENT = '    ';

/** @type {Map<string, string[]|null>} */
const lineCache = new Map();

/** The requested source line, or null when the file cannot be consulted. */
function lookupSourceLine(file, lineNumber) {
  if (!lineCache.has(file)) {
    try {
      lineCache.set(file, readFileSync(file, 'utf8').split(/\r\n|\r|\n/));
    } catch {
      lineCache.set(file, null);
    }
  }
  const lines = lineCache.get(file);
  if (lines === null) return null;
  const line = lines[lineNumber - 1];
  return line === undefined || line === '' ? null : line;
}

/**
 * Build the anchor line for a span, in columns relative to the stripped line.
 *
 * @param {[number, number]} span  Half-open column range of the expression.
 * @param {[number, number]|null} operator  Column range of the operator token
 *   for a binary operation; `null` marks the whole span with carets.
 */
export function anchorLine(span, operator) {
  const [start, end] = span;
  let marks;
  if (operator === null) {
    marks = '^'.repeat(end - start);
  } else {
    const [operatorStart, operatorEnd] = operator;
    marks =
      '~'.repeat(operatorStart - start) +
      '^'.repeat(operatorEnd - operatorStart) +
      '~'.repeat(end - operatorEnd);
  }
  return ' '.repeat(SOURCE_INDENT.length + start) + marks;
}

/**
 * Render and emit a traceback.
 *
 * @param {{file: string, line: number, span: [number, number],
 *          operator: [number, number]|null}} origin  The `<module>` frame.
 * @param {{file: string, line: number, name: string}[]} frames
 *   Library frames below it, outermost first.  The reference build has no
 *   source for those, so only their headers are printed.
 * @param {string} exceptionLine  The trailing `Type: message` line.
 */
export function printTraceback(origin, frames, exceptionLine) {
  let out = 'Traceback (most recent call last):\n';
  out += `  File "${origin.file}", line ${origin.line}, in <module>\n`;

  const rawLine = lookupSourceLine(origin.file, origin.line);
  if (rawLine !== null) {
    const stripped = rawLine.trim();
    const indentWidth = rawLine.length - rawLine.trimStart().length;
    out += `${SOURCE_INDENT}${stripped}\n`;

    const span = [origin.span[0] - indentWidth, origin.span[1] - indentWidth];
    const operator =
      origin.operator === null
        ? null
        : [origin.operator[0] - indentWidth, origin.operator[1] - indentWidth];
    // Anchors are suppressed only when they would cover the whole line and
    // carry no operator detail.
    if (span[1] - span[0] < stripped.length || operator !== null) {
      out += `${anchorLine(span, operator)}\n`;
    }
  }

  for (const frame of frames) {
    out += `  File "${frame.file}", line ${frame.line}, in ${frame.name}\n`;
  }
  out += `${exceptionLine}\n`;
  writeStderr(out);
}

